"use client";

import { useState } from "react";
import Link from "next/link";
import { usePathname } from "next/navigation";
import {
  LayoutDashboard,
  MapPin,
  Cpu,
  Navigation,
  BarChart3,
  HeartPulse,
  LogOut,
  Menu,
  Zap,
  ShieldCheck,
  ChevronDown,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Sheet, SheetContent, SheetTrigger } from "@/components/ui/sheet";
import { logout } from "@/lib/api/auth";
import { useAuth } from "@/context/AuthContext";
import { useRouter } from "next/navigation";

const navItems = [
  { icon: LayoutDashboard, label: "MAIN SCREEN", href: "/" },
  { icon: MapPin, label: "AREA", href: "/area" },
  { icon: Cpu, label: "SENSORS", href: "/sensors" },
  { icon: Navigation, label: "DRONES", href: "/drones" },
  { icon: MapPin, label: "MAP", href: "/maps/manage" },
  
];

export function DashboardHeader() {
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const router = useRouter();
  const pathname = usePathname();
  const { user, refreshUser } = useAuth();

  const isActive = (href: string) => {
    if (href === "/") {
      return pathname === "/";
    }
    return pathname.startsWith(href);
  };

  async function handleLogout() {
    await logout();
    await refreshUser();
    router.push("/login");
  }

  const userName = user?.name || "Operator";
  const userInitial = userName.charAt(0).toUpperCase();

  return (
    <header className="flex h-14 items-center justify-between border-b border-slate-200 bg-white px-3 md:px-5 shadow-xs">
      {/* Brand Text Name */}
      <Link href="/" className="flex items-center gap-2 group py-1">
        <div className="flex items-center gap-2 py-1 px-3 rounded-lg bg-slate-50 border border-slate-200 transition-all duration-200 group-hover:border-slate-300">
          <span className="text-lg md:text-xl font-extrabold tracking-wider text-slate-900">
          SENSOR AND DRONE MANAGEMENT
          </span>
          <span className="hidden sm:inline-block text-xs font-bold tracking-wider text-slate-500 border-l border-slate-200 pl-2">
            SECURITY 
          </span>
        </div>
      </Link>

      <nav className="hidden items-center gap-1.5 xl:flex">
        {navItems.map((item) => {
          if (item.label === "HEALTH") {
            return (
              <Link key={item.label} href={item.href}>
                <Button
                  variant="ghost"
                  size="sm"
                  className={`gap-1.5 px-3 py-1.5 text-xs transition-all duration-150 rounded-lg ${
                    isActive(item.href)
                      ? "bg-red-100 text-red-700 border border-red-300 font-bold shadow-2xs"
                      : "bg-red-50 text-red-600 border border-red-200 hover:bg-red-100 font-semibold"
                  }`}
                >
                  <ShieldCheck className="h-4 w-4 text-red-600" />
                  HEALTH
                </Button>
              </Link>
            );
          }

          return (
            <Link key={item.label} href={item.href}>
              <Button
                variant="ghost"
                size="sm"
                className={`gap-2 px-3 py-1.5 text-xs transition-all duration-150 rounded-lg ${
                  isActive(item.href)
                    ? "bg-slate-100 text-slate-900 border border-slate-200 shadow-2xs font-bold"
                    : "text-slate-600 hover:bg-slate-100 hover:text-slate-900 border border-transparent font-medium"
                }`}
              >
                <item.icon className={`h-4 w-4 ${isActive(item.href) ? "text-slate-900" : "text-slate-500"}`} />
                {item.label}
              </Button>
            </Link>
          );
        })}
      </nav>

      <div className="hidden items-center gap-3 xl:flex">
        {/* User Profile Info */}
        <div className="flex items-center gap-2 px-2.5 py-1 rounded-full bg-slate-100 border border-slate-200">
          <div className="h-6 w-6 rounded-full bg-slate-800 text-white font-bold flex items-center justify-center text-xs">
            {userInitial}
          </div>
          <span className="text-xs font-semibold text-slate-800 max-w-[100px] truncate">
            {userName}
          </span>
        </div>

        {/* Logout */}
        <Button
          variant="ghost"
          size="sm"
          className="gap-1.5 text-xs text-slate-600 hover:bg-slate-100 hover:text-slate-900 transition-all hover:cursor-pointer"
          onClick={handleLogout}
        >
          <LogOut className="h-4 w-4 text-slate-500" />
          LOGOUT
        </Button>
      </div>

      <Sheet open={mobileMenuOpen} onOpenChange={setMobileMenuOpen}>
        <SheetTrigger asChild>
          <Button
            variant="ghost"
            size="icon"
            className="xl:hidden text-slate-800 hover:bg-slate-100"
          >
            <Menu className="h-6 w-6" />
          </Button>
        </SheetTrigger>
        <SheetContent
          side="right"
          className="w-72 border-slate-200 bg-white p-0"
        >
          <div className="flex h-14 items-center justify-between border-b border-slate-200 px-4">
            <span className="text-lg font-bold text-slate-900 tracking-wide">Menu</span>
          </div>
          <nav className="flex flex-col gap-2 p-4">
            {navItems.map((item) => (
              <Link key={item.label} href={item.href}>
                <Button
                  variant="ghost"
                  className={`w-full justify-start gap-3 rounded-lg ${
                    isActive(item.href)
                      ? "bg-slate-100 text-slate-900 border border-slate-200 font-bold"
                      : "text-slate-600 hover:bg-slate-100 hover:text-slate-900"
                  }`}
                  onClick={() => setMobileMenuOpen(false)}
                >
                  <item.icon className={`h-5 w-5 ${isActive(item.href) ? "text-slate-900" : "text-slate-500"}`} />
                  {item.label}
                </Button>
              </Link>
            ))}

            <Link href="/smartmeter">
              <Button
                variant="ghost"
                className={`w-full uppercase justify-start gap-3 rounded-lg ${
                  pathname.startsWith("/smartmeter")
                    ? "bg-slate-100 text-slate-900 border border-slate-200 font-bold"
                    : "text-slate-600 hover:bg-slate-100 hover:text-slate-900"
                }`}
                onClick={() => setMobileMenuOpen(false)}
              >
                <Zap className="h-5 w-5 text-slate-500" />
                Smart Meter
              </Button>
            </Link>

            <div className="my-4 border-t border-slate-200" />

            <Button
              variant="ghost"
              className="justify-start gap-3 text-slate-600 hover:bg-red-50 hover:text-red-600"
              onClick={handleLogout}
            >
              <LogOut className="h-5 w-5" />
              LOGOUT
            </Button>
          </nav>
        </SheetContent>
      </Sheet>
    </header>
  );
}
